  static List<NordCountry> getCountries() {
    final list = jsonDecode(_countriesJson) as List<dynamic>;
    return list
        .whereType<Map<String, dynamic>>()
        .map(NordCountry.fromJson)
        .toList();
  }

  static List<NordServer> getServers({int? countryId}) {
    final list = jsonDecode(_serversJson) as List<dynamic>;
    final all = list.whereType<Map<String, dynamic>>().map((m) {
      return NordServer(
        id: (m['id'] as num).toInt(),
        name: m['name'] as String,
        hostname: m['hostname'] as String,
        stationIp: m['stationIp'] as String,
        load: (m['load'] as num).toInt(),
        countryName: m['countryName'] as String,
        countryCode: m['countryCode'] as String,
        countryId: (m['countryId'] as num).toInt(),
        cityName: m['cityName'] as String,
        publicKey: m['publicKey'] as String,
        hasSslProxy: (m['hasSslProxy'] as bool?) ?? true,
      );
    }).toList();
    if (countryId == null) return all;
    return all.where((s) => s.countryId == countryId).toList();
  }
